/**
 * Pure tests for the crq repair request-context builder.
 *
 * The oracle fixture is generated by
 * `apps/crq-python/repair_request_context_vectors.py`, which runs the
 * PRODUCTION Python `process_item`, `process`, `_dispatch` and `cq.invoke`
 * with only their effects mocked. Every valid case pins the derived context
 * byte for byte; every recorded Python exception maps to one typed refusal.
 * The remaining cases are the deliberate strictness this slice adds so a
 * value the typed op cannot accept is refused instead of forwarded.
 *
 * No process, filesystem write, clock, git read or network participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import {
  buildRepairRequestContext,
  type BuildRepairRequestContextResult,
  type DerivedRepairRequestContext,
  type RepairRequestContextRefusal,
} from '../../../src/policy/crq/repairRequestContext.js';
import type { RepairRequestContext } from '../../../src/policy/crq/repairRequest.js';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';
import { atomicJsonText } from '../../../src/policy/crq/pythonJson.js';

const FIXTURE_URL = new URL(
  '../../../apps/crq-python/fixtures/repair-request-context/cases.json',
  import.meta.url,
);
const SOURCE_URL = new URL('../../../src/policy/crq/repairRequestContext.ts', import.meta.url);
const fixture = asObject(parseJsonValue(readFileSync(FIXTURE_URL, 'utf8')));
const cases = asArray(fixture.get('cases')).map((entry) => asObject(entry));

const JOB_ID = 'crq-revalidated-cb466c2a4e9f4881d7b6c47c-F1';

interface TestRole {
  driver?: unknown;
  model?: unknown;
  budget?: unknown;
}

interface TestRepair {
  budget?: unknown;
  roles?: Record<string, TestRole | null>;
}

interface TestConfig {
  repo?: unknown;
  worktree_root?: unknown;
  repair?: TestRepair | null;
}

const BASE_CONFIG: TestConfig = {
  repo: 'example/repo',
  worktree_root: '/work',
  repair: {
    budget: { wall_clock_min: 20, max_output_tokens: 500_000, max_context_tokens: 200_000 },
    roles: {
      fixer: { driver: 'cq', model: 'zai/glm-5.3-flash' },
      fixer_escalation: { driver: 'cq', model: 'zai/glm-5.3' },
    },
  },
};

// A JSON round-trip keeps every test's mutation independent of the constant.
function configText(patch: (config: TestConfig) => void = () => {}): string {
  const config = JSON.parse(JSON.stringify(BASE_CONFIG)) as TestConfig;
  patch(config);
  return JSON.stringify(config);
}

function repairOf(config: TestConfig): TestRepair {
  if (config.repair === undefined || config.repair === null) throw new Error('missing repair');
  return config.repair;
}

function rolesOf(config: TestConfig): Record<string, TestRole | null> {
  const roles = repairOf(config).roles;
  if (roles === undefined) throw new Error('missing roles');
  return roles;
}

function fixerOf(config: TestConfig): TestRole {
  const role = rolesOf(config).fixer;
  if (role === undefined || role === null) throw new Error('missing fixer role');
  return role;
}

function build(
  text: string,
  options: { readonly role?: string; readonly item?: string; readonly job?: string } = {},
): BuildRepairRequestContextResult {
  return buildRepairRequestContext({
    configText: text,
    role: options.role ?? 'fixer',
    pinned: { item: options.item ?? 'pr1-merged', job: options.job ?? JOB_ID },
  });
}

function valueOf(result: BuildRepairRequestContextResult): DerivedRepairRequestContext {
  expect(result.ok).toBe(true);
  if (!result.ok) throw new Error(`unexpected refusal: ${result.refusal}`);
  return result.value;
}

function expectRefusal(
  result: BuildRepairRequestContextResult,
  refusal: RepairRequestContextRefusal,
): void {
  expect(result).toEqual({ ok: false, refusal });
}

/** Preserve a corrupt fixture value so the refusal case exercises the builder. */
function buildCase(c: JsonObject): BuildRepairRequestContextResult {
  const pinned = asObject(c.get('pinned'));
  const text = (value: JsonValue | undefined): string =>
    typeof value === 'string' ? value : (value as unknown as string);
  return buildRepairRequestContext({
    configText: asString(c.get('config_text')),
    role: asString(c.get('role')),
    pinned: { item: text(pinned.get('item')), job: text(pinned.get('job')) },
  });
}

function asObject(value: JsonValue | undefined): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error('expected a JSON object');
  return value;
}

function asArray(value: JsonValue | undefined): JsonValue[] {
  if (!Array.isArray(value)) throw new Error('expected a JSON array');
  return value;
}

function asString(value: JsonValue | undefined): string {
  if (typeof value !== 'string') throw new Error('expected a JSON string');
  return value;
}

function asNumber(value: JsonValue | undefined): number {
  if (!(value instanceof JsonNumber) || value.kind !== 'int') {
    throw new Error('expected a JSON integer');
  }
  return Number(value.integer);
}

function optionalString(value: JsonValue | undefined): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

function refusalFor(name: string, error: JsonObject): RepairRequestContextRefusal {
  const stage = asString(error.get('stage'));
  const type = asString(error.get('type'));
  const key = optionalString(error.get('key'));
  const attribute = optionalString(error.get('attribute'));
  if (type === 'KeyError') {
    switch (key) {
      case 'repair':
        return 'config-unreadable';
      case 'roles':
      case 'fixer_escalation':
        return 'role-unknown';
      case 'model':
      case 'driver':
        return 'role-invalid';
      case 'repo':
        return 'repo-missing';
      case 'budget':
      case 'wall_clock_min':
        return 'budget-malformed';
      case 'worktree_root':
        return 'worktree-input-missing';
      case undefined:
        break;
    }
  }
  if (type === 'AttributeError') {
    switch (attribute) {
      case 'get':
        return 'budget-malformed';
      case 'split':
        return 'role-invalid';
      case 'rsplit':
        return 'worktree-input-missing';
      case undefined:
        break;
    }
  }
  // Python's formatted TypeError/ValueError text varies between minors; the
  // case name is the stable operation discriminator.
  if (type === 'TypeError') {
    switch (name) {
      case 'missing-roles':
      case 'role-not-object':
        return 'role-unknown';
      case 'worktree-root-not-string':
        return 'worktree-input-missing';
      case 'non-numeric-wall-clock':
        return 'budget-malformed';
      default:
        break;
    }
  }
  if (type === 'ValueError') {
    switch (name) {
      case 'model-without-separator':
        return 'role-invalid';
      case 'non-cq-fixer-driver':
        return 'role-driver-unsupported';
      default:
        break;
    }
  }
  throw new Error(`unexpected Python refusal at ${stage}: ${name} (${type})`);
}

describe('derived context matches the production Python derivation', () => {
  for (const c of cases) {
    if (c.get('error') !== null) continue;
    const name = asString(c.get('name'));
    test(name, () => {
      const result = build(asString(c.get('config_text')), {
        role: asString(c.get('role')),
        item: asString(asObject(c.get('pinned')).get('item')),
        job: asString(asObject(c.get('pinned')).get('job')),
      });
      const value = valueOf(result);

      // Byte-for-byte against Python's own `json.dumps(..., indent=2)` text.
      expect(atomicJsonText(value)).toBe(asString(c.get('context_json')));

      const expected = asObject(c.get('context'));
      expect(value.repo).toBe(asString(expected.get('repo')));
      const worktree = asObject(expected.get('worktree'));
      expect(value.worktree).toEqual({
        path: asString(worktree.get('path')),
        branch: asString(worktree.get('branch')),
      });
      const expectedDriver = asObject(expected.get('driver'));
      expect(value.driver).toEqual({
        provider: asString(expectedDriver.get('provider')),
        model: asString(expectedDriver.get('model')),
      });
      const budget = asObject(expected.get('budget'));
      expect(value.budget).toEqual({
        maxOutputTokens: asNumber(budget.get('maxOutputTokens')),
        maxContextTokens: asNumber(budget.get('maxContextTokens')),
        wallClockMs: asNumber(budget.get('wallClockMs')),
      });
      expect(value.worktree.path).toBe(asString(c.get('worktree')));

      // The derived value is the existing request-context type E2 consumes.
      const context: RepairRequestContext = value;
      expect(context.worktree.branch).toBe('detached');
    });
  }
});

describe('each recorded Python failure is one typed refusal', () => {
  for (const c of cases) {
    const error = c.get('error');
    if (error === null || error === undefined) continue;
    const name = asString(c.get('name'));
    test(name, () => {
      expectRefusal(buildCase(c), refusalFor(name, asObject(error)));
      expect('value' in buildCase(c)).toBe(false);
    });
  }
});

describe('config and role selection refusals', () => {
  test('invalid JSON or a non-object document is unreadable', () => {
    for (const text of ['not json', '[]', 'null', '"config"', '{"repair": "x"}', '{}']) {
      expectRefusal(build(text), 'config-unreadable');
    }
  });

  test('an empty or whitespace role name is missing, an absent name is unknown', () => {
    expectRefusal(build(configText(), { role: '' }), 'role-missing');
    expectRefusal(build(configText(), { role: ' ' }), 'role-unknown');
    expectRefusal(build(configText(), { role: 'judge' }), 'role-unknown');
  });

  test('a non-object roles block or role entry is unknown', () => {
    expectRefusal(build(configText((config) => delete repairOf(config).roles)), 'role-unknown');
    expectRefusal(build(configText((config) => (rolesOf(config).fixer = null))), 'role-unknown');
  });

  test('a role without a driver or model, or with an unusable model, is invalid', () => {
    expectRefusal(build(configText((config) => delete fixerOf(config).driver)), 'role-invalid');
    expectRefusal(build(configText((config) => delete fixerOf(config).model)), 'role-invalid');
    for (const model of ['glm-5.3-flash', '/glm-5.3-flash', 'zai/', '', 5]) {
      expectRefusal(build(configText((config) => (fixerOf(config).model = model))), 'role-invalid');
    }
  });

  test('only the CQ driver is derived; other drivers refuse explicitly', () => {
    for (const driver of ['codex', 'paseo', null, 5]) {
      expectRefusal(
        build(configText((config) => (fixerOf(config).driver = driver))),
        'role-driver-unsupported',
      );
    }
  });
});

describe('repo and budget refusals', () => {
  test('a missing, empty or non-string repo is refused', () => {
    expectRefusal(build(configText((config) => delete config.repo)), 'repo-missing');
    for (const repo of ['', 5, null]) {
      expectRefusal(build(configText((config) => (config.repo = repo))), 'repo-missing');
    }
  });

  test('a missing or non-object budget is malformed', () => {
    expectRefusal(
      build(configText((config) => delete repairOf(config).budget)),
      'budget-malformed',
    );
    for (const budget of [null, [], 'large', 5]) {
      expectRefusal(
        build(configText((config) => (repairOf(config).budget = budget))),
        'budget-malformed',
      );
    }
    expectRefusal(
      build(configText((config) => (fixerOf(config).budget = 'large'))),
      'budget-malformed',
    );
  });

  test('a missing, non-numeric or unusable wall clock is malformed', () => {
    expectRefusal(
      build(
        configText((config) => {
          const budget = repairOf(config).budget as Record<string, unknown>;
          delete budget.wall_clock_min;
        }),
      ),
      'budget-malformed',
    );
    for (const wallClock of [null, 'twenty', true, -1, Number.MAX_SAFE_INTEGER]) {
      expectRefusal(
        build(
          configText((config) => {
            const budget = repairOf(config).budget as Record<string, unknown>;
            budget.wall_clock_min = wallClock;
          }),
        ),
        'budget-malformed',
      );
    }
  });

  test('a non-positive, fractional or boolean token cap is malformed', () => {
    for (const [key, value] of [
      ['max_output_tokens', 0],
      ['max_output_tokens', -1],
      ['max_output_tokens', 1.5],
      ['max_output_tokens', true],
      ['max_output_tokens', 'large'],
      ['max_context_tokens', 0],
      ['max_context_tokens', 1.5],
    ] as const) {
      expectRefusal(
        build(
          configText((config) => {
            const budget = repairOf(config).budget as Record<string, unknown>;
            budget[key] = value;
          }),
        ),
        'budget-malformed',
      );
    }
  });

  test('role overrides win over base caps and base caps win over the defaults', () => {
    const overridden = valueOf(
      build(
        configText((config) => {
          fixerOf(config).budget = { max_output_tokens: 123, max_context_tokens: 456 };
        }),
      ),
    );
    expect(overridden.budget).toEqual({
      maxOutputTokens: 123,
      maxContextTokens: 456,
      wallClockMs: 1_200_000,
    });

    const base = valueOf(
      build(
        configText((config) => {
          repairOf(config).budget = { wall_clock_min: 2, max_output_tokens: 700 };
        }),
      ),
    );
    expect(base.budget).toEqual({
      maxOutputTokens: 700,
      maxContextTokens: 200_000,
      wallClockMs: 120_000,
    });

    const defaults = valueOf(
      build(configText((config) => (repairOf(config).budget = { wall_clock_min: 0 }))),
    );
    expect(defaults.budget).toEqual({
      maxOutputTokens: 500_000,
      maxContextTokens: 200_000,
      wallClockMs: 0,
    });
  });
});

describe('pinned worktree inputs and path derivation', () => {
  test('an empty or non-string worktree root, item or job is refused', () => {
    expectRefusal(
      build(configText((config) => (config.worktree_root = ''))),
      'worktree-input-missing',
    );
    expectRefusal(
      build(configText((config) => (config.worktree_root = 5))),
      'worktree-input-missing',
    );
    expectRefusal(build(configText(), { item: '' }), 'worktree-input-missing');
    expectRefusal(build(configText(), { job: '' }), 'worktree-input-missing');
    expectRefusal(
      buildRepairRequestContext({
        configText: configText(),
        role: 'fixer',
        // Runtime casts: the type requires strings, a corrupt caller may not.
        pinned: { item: 5 as unknown as string, job: JOB_ID },
      }),
      'worktree-input-missing',
    );
  });

  test('the escalation role dispatches against the A2 worktree', () => {
    const escalation = valueOf(build(configText(), { role: 'fixer_escalation' }));
    expect(escalation.worktree.path).toBe(`/work/crq-repair-pr1-merged-${JOB_ID}-A2`);
  });

  test('the fixer role keeps the base worktree', () => {
    const fixer = valueOf(build(configText(), { role: 'fixer' }));
    expect(fixer.worktree.path).toBe(`/work/crq-repair-pr1-merged-${JOB_ID}`);
  });

  test('the path matches Python PurePosixPath joining', () => {
    const expected = (root: string, item: string, job: string): string =>
      valueOf(
        build(
          configText((config) => (config.worktree_root = root)),
          { item, job },
        ),
      ).worktree.path;
    expect(expected('/w//a/', 'it', 'jo')).toBe('/w/a/crq-repair-it-jo');
    expect(expected('/', 'it', 'jo')).toBe('/crq-repair-it-jo');
    expect(expected('//', 'it', 'jo')).toBe('//crq-repair-it-jo');
    expect(expected('///', 'it', 'jo')).toBe('/crq-repair-it-jo');
    expect(expected('//a//b', 'it', 'jo')).toBe('//a/b/crq-repair-it-jo');
    expect(expected('.', 'it', 'jo')).toBe('crq-repair-it-jo');
    expect(expected('/w/./a', 'it', 'jo')).toBe('/w/a/crq-repair-it-jo');
    expect(expected('/w', 'pr 7 (merged)', 'crq-backfill-ab/c')).toBe(
      '/w/crq-repair-pr 7 (merged)-crq-backfill-ab/c',
    );
    expect(expected('/w', 'pr-雪', 'crq-😀-F1')).toBe('/w/crq-repair-pr-雪-crq-😀-F1');
  });
});

describe('the builder stays pure and deterministic', () => {
  test('the module has no I/O, clock, process or network surface', () => {
    const source = readFileSync(SOURCE_URL, 'utf8');
    for (const forbidden of [
      "from 'node:",
      'from "node:',
      'Date.now',
      'new Date',
      'Math.random',
      'child_process',
      'readFile',
      'writeFile',
      'fetch(',
      'process.env',
    ]) {
      expect(source).not.toContain(forbidden);
    }
  });

  test('repeated calls with the same text return equal values', () => {
    const text = configText();
    const first = valueOf(build(text));
    const second = valueOf(build(text));
    expect(second).toEqual(first);
    expect(atomicJsonText(second)).toBe(atomicJsonText(first));
  });

  test('the fixture names the production functions it was recorded from', () => {
    const source = asArray(fixture.get('source'))
      .map((entry) => asString(entry))
      .join('\n');
    expect(source).toContain('crq_repair.py:process_item');
    expect(source).toContain('crq_repair.py:process');
    expect(source).toContain('crq_repair.py:_dispatch');
    expect(source).toContain('drivers/cq.py:invoke');
    expect(source).toContain('drivers/cq.py:budget');
  });
});
